body.script:
//
/* Cách thêm bài: thêm một đối tượng vào ĐẦU mảng POSTS (bài mới nhất đứng trước). - slug: chữ thường, không dấu, nối bằng dấu gạch ngang - date: ngày đăng, ví dụ "13/10/2026" - mach: "Chuyện thật" hoặc "Đất Thủ Tu Chân Ký" - tags: các dấu để người đọc lọc, ví dụ ["Tâm Ma", "Học phí"]; để trống nếu không cần - body: mỗi phần tử là một đoạn; thêm beat: true cho đoạn rất ngắn đổi nhịp Đoạn đầu cũng là phần trích trên trang chủ, nên đoạn đầu phải có lực kéo. */ var POSTS = [ { slug: "ngay-doanh-nhan-noi-so-hai", date: "13/10/2026", mach: "Chuyện thật", tags: ["Tâm Ma"], title: "Ngày Doanh nhân: nỗi sợ hãi khi phải lựa chọn", body: [ { t: "Sáng nay, bần đạo ngồi thiền cùng anh em trong công ty. Xả thiền xong, mọi người đi làm. Bần đạo còn ngồi lại vài phút. Công ty không vì vừa ngồi thiền mà tự nhiên hết bài toán, nhưng đầu óc bớt ồn một chút. Và một cuộc họp cũ tự dưng quay lại." }, { t: "Khách hỏi về một phương án rất đẹp: “Bên em làm được không?”" }, { t: "Đội kỹ thuật nói: “Làm được anh. Nhưng rủi ro an toàn cao.” Khách nhìn bần đạo: “Nếu bên khác nhận làm thì sao?” Câu này làm bần đạo khựng lại." }, { t: "Thật ra bần đạo tiếc chứ. Tiếc hợp đồng. Tiếc công sức đã theo đuổi. Tiếc cả cảm giác sắp chốt được một việc lớn. Cuối tháng, bảng lương không tự ngồi thiền cùng mình." }, { t: "Tâm Ma bảo: “Thì nói làm được. Mình đã báo rủi ro rồi. Khách vẫn chọn mà. Mình đâu có lừa ai.” Nghe rất hợp lý." }, { t: "Bần đạo hỏi lại đội kỹ thuật: “Nếu làm, ai sẽ là người chịu phần rủi ro đó?” Một bạn đáp: “Anh em ở hiện trường.”" }, { t: "Bần đạo quay sang khách: “Nếu anh vẫn chọn cách này, bên em xin không nhận.” Khách không nói gì thêm. Cuộc họp kết thúc." }, { t: "Bần đạo không biết anh có tìm một đơn vị khác hay không. Chỉ biết từ lúc bước ra khỏi phòng, câu “nếu bên khác nhận làm thì sao?” cứ đi theo mình." }, { t: "Mấy ngày sau, bần đạo phỏng vấn một ứng viên." }, { t: "Bạn có năng lực. Công ty đang cần người. Bần đạo nói về công việc, cơ hội và những điều bạn có thể làm nếu vào đây." }, { t: "Bạn nghe xong rồi hỏi: “Công ty đang cần em giải quyết bài toán nào ưu tiên vậy anh?”" }, { t: "Tâm Ma lại nói: “Nói vừa vừa thôi. Đang tuyển người, không phải đang tổ chức thi tuyển chịu khổ. Kể hết nó thấy khó thì sao vào?”" }, { t: "Bần đạo nhìn hồ sơ của bạn. Chỉ cần nói thêm vài câu đẹp, có thể buổi phỏng vấn này sẽ có một cái gật đầu." }, { t: "Nhưng bần đạo nhớ đến người khách mấy hôm trước." }, { t: "Bần đạo nói: “Anh đang cần người giải bài toán này. Nguồn lực hiện tại mới có tới đây. Có những phần em sẽ phải tự tìm đường. Anh nói để em biết trước khi chọn.” Bạn im một lúc rồi nói: “Vậy để em suy nghĩ.”" }, { t: "Lại một câu “để em suy nghĩ”.", beat: true }, { t: "Bần đạo ngồi trong phòng họp, thấy nó giống hệt câu của người khách." }, { t: "Bần đạo không nói sai với cả hai người. Chỉ là nếu không nói phần còn lại, thì cái gật đầu của họ có thật sự là lựa chọn của họ không?" }, { t: "Ngày Doanh nhân năm nay, bần đạo không biết chúc gì cho mình. Chỉ thấy may là còn nhìn thấy cái vực thẳm nằm ở cuối một câu “dạ được”, khi mình vẫn chưa rơi xuống đó." } ] }, { slug: "cai-do-nguoi-khac", date: "07/10/2026", mach: "Chuyện thật", tags: ["Tâm Ma"], title: "Cái dở người khác là… bần đạo nhớ dai lắm", body: [ { t: "Bần đạo từng xem một video. Một người thầy viết lên bảng 10 phép nhân, chín phép đúng, một phép sai. Xong thầy quay xuống hỏi: “Các em thấy gì?”. Cả lớp chỉ ngay vào phép sai. Chẳng ai nói gì về chín phép đúng." }, { t: "Bần đạo xem xong gật gù. Ờ, cũng thâm. Rồi… lướt tiếp." }, { t: "Mấy hôm trước, ngồi xem lại công việc của một người đã làm với mình khá lâu, tự nhiên trong đầu bần đạo lôi ra đủ thứ. Cái này từng trễ. Chuyện kia làm chưa tới. Có việc nói mấy lần rồi vẫn bị lại. Mà mấy cái lỗi lặp đi lặp lại mới bực: “Trời đất, cái này nói hoài rồi mà?”" }, { t: "Nhưng nghĩ lại cũng hơi kỳ. Nếu bạn ấy dở như những gì bần đạo đang nhớ thì chắc đã chẳng làm với nhau tới giờ. Bao nhiêu việc vẫn giao, việc khó vẫn làm, lúc cần vẫn gánh. Vậy mà cứ tới lúc đánh giá hay tính giao thêm việc gì, mấy cái dở lại chen lên trước." }, { t: "“Khoan, cái này lần trước bạn ấy bị rồi.” “Chỗ này bạn ấy hay dính lắm.” “Giao nữa có khi lại ăn đủ…”" }, { t: "Khổ cái, toàn chuyện có thật. Thế mới mệt. Tâm Ma chẳng cần bịa thêm câu nào, cứ lôi chuyện cũ ra là bần đạo thấy mình có lý ngay." }, { t: "Đang rất có lý thì tự nhiên nhớ tới ông thầy hôm nọ." }, { t: "CHÍN ĐÚNG. MỘT SAI." }, { t: "Bần đạo thử ngồi nhớ mấy năm qua bạn ấy đã làm tốt những gì. Có chứ. Cũng nhiều." }, { t: "Nhưng phải ngồi nghĩ mới ra.", beat: true }, { t: "Còn mấy cái dở thì thôi rồi. Tâm Ma mở đúng thư mục, đúng file, có cái mấy năm rồi vẫn còn nguyên, chẳng cần tìm." }, { t: "Bần đạo ngồi đó một lúc. Lại nhớ cái bảng của ông thầy." }, { t: "Chín phép đúng. Một phép sai." }, { t: "Tự nhiên hai chữ chạy ngang qua đầu: HẮC HÓA." }, { t: "Bần đạo đang định nghĩ tới người khác.", beat: true }, { t: "Mà thôi.", beat: true } ] }, { slug: "benh-an-mat-tien", date: "09/09/2026", mach: "Chuyện thật", tags: ["Học phí"], title: "Bệnh án: không chịu học cho đến khi… mất tiền", body: [ { t: "Bần đạo đi học từ bé đến lớn, nhưng mắc một bệnh mãn tính: học mà không biết học để làm gì. Chữ vào khá nhiều. Công lực tăng bao nhiêu thì chưa đo được." }, { t: "Sau này ra đời gặp một vị danh y tên Cuộc Đời Chân Nhân. Phác đồ của ngài khá đơn giản: nói không nghe thì cho sai. Sai chưa tỉnh thì cho mất tiền. Mất tiền vẫn chưa tỉnh thì… cho trả hậu quả thêm vài năm." }, { t: "Bần đạo thuộc nhóm kháng thuốc khá tốt. Có vài bài học kinh doanh trước đây, đến giờ vẫn đang đóng học phí. Tính lạc quan thì còn khoảng 10–15 năm nữa mới thanh toán hết liệu trình." }, { t: "Dạo này bệnh nhân bắt đầu hơi rén, nên thử đổi phác đồ: học trước khi phát bệnh." }, { t: "Vừa rồi bần đạo đi học SLII. Ngồi dưới thấy hiểu lắm. Về công ty, đứng lên dạy lại cho anh em mới phát hiện:" }, { t: "À…", beat: true }, { t: "Hóa ra lúc đó mình chỉ hiểu… thầy đang nói gì." }, { t: "Có những chỗ tưởng thuộc rồi, nói ra lại vấp. Có những chữ tưởng cả phòng hiểu giống nhau, hỏi kỹ mới thấy mỗi đạo hữu đang luyện một môn. “Chủ động” một kiểu. “Trao quyền” một kiểu. “Chịu trách nhiệm” lại thêm vài kiểu. Suýt nữa thành đại hội đấu pháp." }, { t: "Thôi thì học tiếp. Vì bần đạo đang cố cai một phương pháp học cực kỳ hiệu quả: mất tiền → đau → ngộ ra." }, { t: "Cuộc Đời Chân Nhân dạy rất chắc. Chỉ có điều ngài không báo học phí trước." }, { t: "Mà có những bài…" }, { t: "học một ngày,", beat: true }, { t: "trả góp mười năm.", beat: true } ] }, { slug: "cang-tin-nhan-vien-cang-that-vong", date: "07/08/2026", mach: "Chuyện thật", tags: [], title: "Tại sao càng tin nhân viên, bần đạo lại càng… thất vọng?", body: [ { t: "Chiều nay bần đạo có hai buổi làm việc với hai nhân sự. Hai vị trí khác nhau. Hai câu chuyện khác nhau. Nhưng nghe một hồi lại thấy hơi quen." }, { t: "Hình như bệnh cũ của mình." }, { t: "Có một thời gian Đất Thủ tuyển khá nhiều vị trí quản lý. Người vào rồi người ra. Có người không qua thử việc. Có người đi được một đoạn rồi dừng. Bần đạo lúc ấy khá khó hiểu. “Ủa, đã từng làm quản lý rồi mà?” “Việc này cũng phải hướng dẫn sao?” “Sao cái này cũng không biết?”" }, { t: "Mình tin một nguyên tắc nghe rất hay: “Đã tin thì phải giao.” Thế là giao thật. Đây là mục tiêu. Đây là kết quả. Anh tin em. Triển khai đi. Trong đầu bần đạo gọi đó là trao quyền." }, { t: "Rồi vài ngày sau bắt đầu: “Tới đâu rồi em?” “Dạ, em đang làm.” “Đang… là đang tới đâu?”" }, { t: "À.", beat: true }, { t: "Lão Quản Lý ở Hồi 4 bắt đầu nhập xác." }, { t: "Có việc mình nghĩ ba ngày là xong, một tuần sau vẫn còn. Có việc mình tưởng đã nói rất rõ, người nhận lại chẳng biết bắt đầu từ đâu. Bần đạo bắt đầu thất vọng. “Sao việc này cũng không biết làm?”" }, { t: "Mãi sau này, có lần đang hướng dẫn lại một việc, mình chợt hỏi: “Cái này trước giờ có ai nói với em chưa?” “Dạ chưa.” “Còn cái này?” “Cũng chưa anh.” “Vậy sao em biết phải làm thế này?”" }, { t: "Bạn ấy nhìn mình. Bần đạo nhìn bạn ấy. Không khí bắt đầu có mùi giác ngộ." }, { t: "Hóa ra có những thứ mình làm mấy năm nên tưởng nó là kiến thức phổ thông. Người mới vào chắc… tự tải về được. Bối cảnh chưa nói. Kỳ vọng chưa làm rõ. Cách mình muốn phối hợp cũng chưa nói. Xong rồi bần đạo ngồi chờ người ta làm đúng cái mình đang nghĩ trong đầu." }, { t: "Công pháp này xem ra còn khó hơn Tha Tâm Thông. Vì lần này mình yêu cầu nhân viên phải đọc được tâm của CEO." }, { t: "Chiều nay, sau hai cuộc nói chuyện, bệnh cũ lại hơi tái phát. Bần đạo đang định nghĩ: “Sao cái này cũng phải nói?” May mà kịp dừng lại." }, { t: "Ừ.", beat: true }, { t: "Có khi phải nói thật. Vì…" }, { t: "mình chưa từng nói.", beat: true } ] }, { slug: "anh-tin-em-nhung-khong-chon-em", date: "03/08/2026", mach: "Chuyện thật", tags: [], title: "Anh tin em, nhưng anh không chọn em", body: [ { t: "5 năm trước, có một buổi chiều mình vẫn nhớ. Ngồi đối diện là một người anh, tách trà giữa hai người cứ nguội dần. Anh nói sẽ không hợp tác với mình. Gọn vậy thôi. Mình về, trong đầu lúc ấy chỉ nghĩ: chắc anh chưa đủ tin mình." }, { t: "Mấy năm sau, hai anh em lại ngồi cà phê. Chẳng bàn công việc gì, anh bỗng nói: “Hồi đó anh không chọn em, không phải vì anh không tin em đâu.”" }, { t: "Mình im. Câu này hình như đã đợi 5 năm rồi." }, { t: "Anh nói anh tin mình về con người. Nhiệt tình có, cầu thị có. Nhưng việc ấy quan trọng với anh quá, và lúc đó… mình chưa đủ sức làm." }, { t: "Nghe cũng hơi đau. Nhưng lạ là 5 năm sau nghe lại, mình không còn thấy khó chịu như trước. Có lẽ vì lúc này bần đạo đã đổi ghế. Ngày trước là người ngồi chờ được chọn. Bây giờ lại thành người phải chọn." }, { t: "Và có những lúc mình gặp một người rất tốt, rất trách nhiệm, rất muốn làm. Mình cũng rất quý. Nhưng tới lúc đặt họ vào một vị trí quan trọng, tay lại dừng." }, { t: "Ngày xưa mình từng nghĩ: “Đã tin thì phải giao.” Bây giờ có lúc định nói câu ấy, mình lại nhớ tới tách trà năm nào." }, { t: "Có lần một bạn hỏi gần như đúng điều mình từng muốn hỏi: “Anh chưa tin em à?” Bần đạo suýt trả lời ngay. Rồi khựng lại." }, { t: "“Anh tin em. Nhưng việc này, anh chưa dám chọn em.”" }, { t: "Hai câu đứng cạnh nhau nghe hơi trái khoáy. 5 năm trước mình cũng không hiểu. Thậm chí người anh năm ấy chỉ nói “không”, còn phần “anh ấy không tin mình” là do bần đạo tự điền vào." }, { t: "Tha Tâm Thông luyện chưa thành mà ngày ấy đã dùng khá tự tin. Mất 5 năm mới biết… dịch sai." }, { t: "Bây giờ tới lượt mình ngồi ở phía bên kia bàn. Mới thấy không chọn một người đôi khi cũng là một câu khá khó nói." }, { t: "Người anh năm ấy xem ra công lực cao hơn mình một cảnh giới. Ít nhất anh dám không chọn mình." }, { t: "Còn mình lúc đó…" }, { t: "chỉ chăm chăm muốn được chọn.", beat: true } ] }, { slug: "ca-khong-thay-nuoc", date: "25/03/2026", mach: "Chuyện thật", tags: [], title: "Cá không thấy nước", body: [ { t: "Hồi cấp 3, mình đi học vì bố mẹ bắt. Không phản đối. Cũng không có khát vọng phải đứng đầu. Chỉ có một điều mình muốn… đừng bị thua ai, đừng bị nhắc nhở, đừng bị mời phụ huynh." }, { t: "Đi làm những năm đầu, mình cũng vậy. Không xuất sắc nhất. Không kém nhất. Cứ ở giữa, đủ để sếp đừng để ý. Mình từng nghĩ đó là bình thường." }, { t: "Bây giờ, sau 30 năm và một thất bại, mình biết một con cá sống cả đời trong nước thì không bao giờ thấy được nước. Nó tưởng nước là không khí. Tưởng đó là tất cả." }, { t: "Cả đời mình bơi trong một câu nói thầm: “Đừng bị thua. Đủ thôi là được.”" }, { t: "Cấp 3, sợ bị mời phụ huynh. Đi làm, sợ bị sếp đánh giá. Sống, sợ bị người ta thấy mình kém. Mỗi giai đoạn cuộc đời, cùng một câu. Chỉ đổi sân khấu thôi." }, { t: "Mình không cố ý chọn câu nói thầm này. Nó tự đến, như nỗi sợ ai cũng có. Mình chỉ không thấy còn cách nào khác." }, { t: "2016, mình mở công ty. Hai năm đầu chạy trong vùng quen. Năm 2018, mình bước vào một dự án lớn hơn vùng quen của mình. Phức tạp hơn. Đụng những thứ mình chưa từng làm. Đến 2019, mình thất bại. Nặng. Phải bồi thường hợp đồng. Tổn thất tài chính rất lớn." }, { t: "Trong những đêm sau đó, có một câu hỏi mình không tránh được: “Vì sao tôi đến đây?” Không phải đến chỗ thất bại này. Là đến chỗ tôi đã đứng cả đời, chỗ vừa đủ, không hơn." }, { t: "Câu trả lời đau nhất mà mình thấy: tôi không thất bại vì làm sai. Tôi thất bại vì lần đầu tiên có một dự án quá lớn cho cách sống “vừa đủ” của tôi." }, { t: "Khi cá bị quăng khỏi nước, lần đầu tiên nó thấy nước. Vì lần đầu tiên nó không có nước để bơi." }, { t: "Trước 2018, mình từng có lúc thành công, quy mô tốt, làm cùng anh em, có lợi nhuận. Mình tưởng đó là bằng chứng mình đúng. Bây giờ mình biết: thành công đó không phải vì mình đúng. Là vì bể nước cũ vẫn còn vừa với mình. Cá bơi tốt trong bể quen, không có nghĩa nó biết mình đang ở trong nước." }, { t: "Sau thất bại, mình tiếp tục với ngành kiến trúc xây dựng, gần với chuyên ngành thiết kế nội thất mình đã học. Hai năm đầu công ty hoạt động không có triết lý. Mình làm vì phải làm. Cùng cách sống cũ, chỉ đổi nghề mới." }, { t: "Cho đến khi đọc cuốn sách của Inamori Kazuo, mình tìm được câu cho công ty: phục vụ bằng sự tử tế. Có triết lý. Hết hai năm vô triết lý." }, { t: "Nhưng ba năm sau, một bạn nhân viên hỏi: “Tầm nhìn sứ mệnh công ty mình là gì?” Mình ngồi với câu hỏi đó. Không trả lời được. Câu hỏi quá lớn. Hay nói thật hơn, kiến thức mình không đủ để trả lời. Cuối cùng mình phải thuê chuyên gia bên ngoài giúp tìm câu trả lời." }, { t: "Một CEO 40 tuổi, làm doanh nghiệp nhiều năm, đã đi thiền 11 năm, vẫn phải thuê người khác để thấy điều mình muốn cho công ty mình." }, { t: "Đây là điều khó nói nhất với mình hôm nay: 11 năm đi thiền không cho mình thấy được nước." }, { t: "Thiền dạy mình quan sát những phản ứng nhỏ trong tâm, bực, vui, sợ. Nhưng thiền không tự động cho mình thấy cách sống cả đời mình. Cái lớn quá. Cái mình đang sống bên trong. Cá đi thiền 11 năm vẫn là cá. Vẫn không tự thấy được nước. Phải có người đứng ngoài bể chỉ vào, “đó, anh đang ở trong cái đó”, cá mới thấy." }, { t: "Hai năm mình né câu hỏi tầm nhìn không phải vì quên. Mình né bằng cách nói “câu này chung chung quá”. Bằng cách “để khi nào rảnh sẽ nghĩ”. Bằng cách làm những việc nhỏ trước. Cá bận bơi. Cá không có thời gian thấy nước." }, { t: "Hôm nay mình có triết lý từ Inamori. Có tầm nhìn sứ mệnh nhờ chuyên gia. Có 11 năm đi thiền. Có cả thất bại 2018 và 2019 dạy mình thấy. Nhưng có những đêm khó, sau cuộc họp căng, sau quyết định lớn, sau khi khách hàng từ chối, tâm vẫn nói: “Đủ thôi là được. Đừng cố quá.”" }, { t: "Câu nói thầm cũ vẫn còn. Sau tất cả." }, { t: "Khác là, bây giờ mình nghe được nó. Trước đây nó nói, mình tin liền. Bây giờ nó nói, có một khoảng trống nhỏ trước khi mình tin. Trong khoảng trống đó, mình kịp hỏi: “Đây là tâm khôn ngoan, hay là thói cũ đang chảy?”" }, { t: "Đa số lần mình không phân biệt được. Đôi khi phân biệt được. Đó là tất cả khác biệt." }, { t: "Cá thấy nước rồi cũng không thoát ra khỏi nước được. Cá vẫn phải bơi trong nước. Khác là cá biết mình đang bơi. Cách sống cũ không biến mất sau khi mình thấy. Chỉ bớt dẫn dắt mình hơn. Đó đã là tất cả những gì 11 năm tu cho mình, và mình đã chấp nhận điều đó." }, { t: "Câu hỏi mình muốn để lại, không phải về thiền, không phải về thất bại:" }, { t: "Có cái gì đang chảy quanh bạn, mà bạn tưởng là không khí?", beat: true }, { t: "Có thể là một câu nói thầm cũ. Có thể là một nỗi sợ quen đến mức không còn thấy nó là sợ. Có thể là một cách sống an toàn quen tới mức bạn nghĩ đó là chính bạn." }, { t: "30 năm cuộc đời mình là không thấy nước. Mình vấp một thất bại lớn để thấy. Bạn không cần đến mức đó để thấy. Có thể chỉ cần một câu hỏi đặt đúng lúc." } ] }, { slug: "tu-tin-hay-nga-man", date: "18/06/2025", mach: "Chuyện thật", tags: [], title: "Tự tin hay ngã mạn: nhìn lại mình sau 5 năm, từ một bài viết cũ", body: [ { t: "Không biết mọi người có bao giờ tình cờ đọc lại một đoạn nhật ký, một status cũ, hay một khoảnh khắc mà ngày xưa mình từng rất tự hào, rồi bỗng thấy… mắc cười?" }, { t: "Thấy sao lúc đó mình… ngây thơ quá. Thấy cũng chân thành thiệt, nhưng có gì đó hơi nông nổi. Có chút gì gọi là tự tin non trẻ, hay nếu nói thẳng ra, là ngã mạn mà lúc đó chưa thấy." }, { t: "Sáng nay, tôi cũng rơi vào đúng một khoảnh khắc như vậy. Vô tình đọc lại bài viết cách đây 5 năm, sau chuyến tham quan văn phòng VNG. Tựa đề bài viết lúc đó là: “Có không biết hưởng… Sáng Trần vô minh!”" }, { t: "Lúc ấy, tôi tin rằng mình đang rất “biết khiêm tốn”. Tự nhủ rằng đội mình chưa bằng người ta, nhưng cũng không kém. Tự tin rằng anh em mình cũng rất giỏi, chỉ là… chưa đủ điều kiện. Nghe có vẻ hợp lý. Nghe cũng giống như một cách động viên tích cực." }, { t: "Nhưng sáng nay đọc lại… tôi thấy ngại. Vì tôi nhận ra phiên bản đó của mình có phần… ngã mạn tinh vi." }, { t: "Ngã mạn không phải lúc nào cũng là huênh hoang. Mà là khi trong đầu mình có một tiếng nói thì thầm: “Người ta giỏi, nhưng tụi mình cũng đâu thua kém gì…” Nó không ồn ào. Nó không khoe khoang. Nhưng nó là một lớp phòng vệ rất khéo của cái tôi. Một sự tự tin mà chưa đủ chín." }, { t: "Bây giờ, khi có dịp bước vào một môi trường tương tự, tôi không còn thấy cần so sánh. Không còn nghĩ “tụi mình cũng làm được vậy”. Chỉ còn thấy rõ: mình còn nhiều điều phải học. Và thật may mắn khi vẫn còn cơ hội để tiếp tục học." }, { t: "Tự tin thật sự, có lẽ là khi mình dám thấy rõ sự chưa đủ của bản thân, mà lòng vẫn yên. Không phải để tự trách. Cũng không phải để chứng minh. Chỉ là để tiếp tục sống tử tế và học mỗi ngày." }, { t: "Tôi nhớ một lời dạy của Thiền sư Ajahn Chah: “Người trí thì giống như mặt đất. Ai đổ sạch hay rác rưởi gì cũng tiếp nhận được, rồi tự chuyển hóa. Còn người ngã mạn, chỉ cần một lời trái ý… là bật lại.” Cầu mong mình học được cách làm đất. Để lắng. Để nhận. Và để không ngừng chuyển hóa." }, { t: "Và rồi, viết tới đây… tôi tự hỏi: “Nếu một người đang cố gắng không ngã mạn, thì đó có phải là một dạng ngã mạn khác không?”" }, { t: "Tôi không biết câu trả lời. Chỉ biết… chắc mình vẫn còn phải học tiếp." } ] } ];
var EN = {"ngay-doanh-nhan-noi-so-hai": {"title": "Entrepreneurs' Day: the fear of having to choose", "body": ["This morning, Bần đạo sat in meditation with the team. After the sit, everyone went to work. Bần đạo stayed a few more minutes. The company's problems don't vanish just because we sat, but the head gets a little quieter. And an old meeting came back on its own.", "The client asked about a very attractive plan: “Can your side do it?”", "The technical team said: “We can, boss. But the safety risk is high.” The client looked at Bần đạo: “And if another contractor takes it?” That question stopped me cold.", "Honestly, I did feel the loss. The contract. The effort already spent chasing it. Even the feeling of being close to closing something big. At the end of the month, the payroll doesn't sit in meditation with you.", "Tâm Ma said: “Just say we can do it. We already warned them about the risk. They still chose it. We're not lying to anyone.” It sounded very reasonable.", "Bần đạo asked the technical team: “If we do it, who carries that risk?” One of them answered: “The crew on site.”", "Bần đạo turned to the client: “If you still choose this way, we respectfully decline.” The client said nothing more. The meeting ended.", "Bần đạo doesn't know whether he found another contractor. I only know that from the moment I left the room, “what if another contractor takes it?” kept following me.", "A few days later, Bần đạo interviewed a candidate.", "A capable person. The company needed people. Bần đạo talked about the work, the opportunities, what they could do if they joined.", "After listening, they asked: “Which problem does the company need me to solve first?”", "Tâm Ma spoke again: “Go easy. We're hiring, not running a hardship contest. If you tell them everything, they'll find it too hard. Why would they join?”", "Bần đạo looked at the résumé. A few more nice sentences, and this interview might end with a nod.", "But Bần đạo remembered the client from a few days earlier.", "Bần đạo said: “I need someone to solve this problem. Our resources only reach this far for now. There are parts where you'll have to find your own way. I'm telling you so you know before you choose.” They were quiet for a moment, then said: “Let me think about it.”", "Another “let me think about it.”", "Bần đạo sat in the meeting room and thought it sounded exactly like the client's.", "Bần đạo hadn't said anything false to either of them. But if I leave out the rest, is their nod really their own choice?", "This Entrepreneurs' Day, Bần đạo doesn't know what to wish for himself. Only that I'm lucky to still see the abyss at the end of a “yes, we can,” while I haven't fallen into it."]}, "cai-do-nguoi-khac": {"title": "Other people's flaws… Bần đạo remembers them for a very long time", "body": ["Bần đạo once watched a video. A teacher wrote ten multiplications on the board, nine right, one wrong. Then he turned to the class: “What do you see?” The whole class pointed straight at the wrong one. Nobody said a word about the nine right ones.", "Bần đạo nodded along. Hm, quite sharp. Then… scrolled on.", "A few days ago, going over the work of someone who has been with me a long time, my head suddenly pulled out everything. That one was late. This one wasn't finished. That thing I'd said several times and it still came back. And the repeated mistakes irritate most: “Heavens, haven't I said this a hundred times?”", "But thinking again, it's a little strange. If this person were as bad as what I'm remembering, we wouldn't have worked together until now. All that work I still hand over, the hard jobs still done, the times they carried the load. Yet every time I evaluate, or think of giving more, the flaws push to the front.", "“Wait, last time this person got caught.” “They often trip right here.” “Give more and they may take the full hit…”", "The trouble is, all of it is true. That's what makes it tiring. Tâm Ma doesn't need to invent a single line. It just pulls out the old stories, and Bần đạo feels right at once.", "Right in the middle of feeling right, I suddenly remembered the teacher from the other day.", "NINE RIGHT. ONE WRONG.", "Bần đạo tried to sit and recall what this person had done well over the years. There was plenty. Quite a lot, actually.", "But I had to sit and think to find it.", "The flaws, though. Tâm Ma opens the exact folder, the exact file, some still intact after years, no searching needed.", "Bần đạo sat there a while. Remembered the teacher's board again.", "Nine right. One wrong.", "Suddenly two words ran across my head: BLACKENING.", "Bần đạo was about to think about someone else.", "Never mind."]}, "benh-an-mat-tien": {"title": "Medical record: refused to learn until… money was lost", "body": ["Bần đạo has studied from childhood to adulthood, yet suffers from one chronic illness: studying without knowing what for. Plenty of words went in. How much my skill grew, nobody has measured.", "Later, out in the world, I met a famous physician named Master Life (Cuộc Đời Chân Nhân). His prescription is quite simple: if telling doesn't work, let them get it wrong. If getting it wrong doesn't wake them, let them lose money. If losing money still doesn't wake them… let them pay the consequences for a few more years.", "Bần đạo belongs to the group that resists medicine rather well. Some business lessons from the past I am still paying tuition for. Optimistically, another 10–15 years before the course of treatment is fully paid.", "Lately the patient has started to get a little nervous, so he's trying a new prescription: study before falling ill.", "Recently Bần đạo went to learn SLII. Sitting in the audience, it all made sense. Back at the company, standing up to teach the team, I discovered:", "Ah…", "It turns out that back then I had only understood… what the teacher was saying.", "Some parts I thought I knew, and tripped when I said them aloud. Some words I thought the whole room understood the same way, and on closer questioning every fellow cultivator was practicing a different art. “Proactive” one way. “Empowerment” another way. “Responsibility” a few more ways. We almost had a martial arts tournament.", "So, back to studying. Because Bần đạo is trying to quit an extremely effective way of learning: lose money → pain → wake up.", "Master Life teaches very firmly. The only catch is that he doesn't announce the tuition in advance.", "And some lessons…", "learned in a day,", "paid in installments over ten years."]}, "cang-tin-nhan-vien-cang-that-vong": {"title": "Why does Bần đạo get more disappointed the more he trusts his staff?", "body": ["This afternoon Bần đạo had two work sessions with two employees. Two different positions. Two different stories. But after listening for a while, it all sounded familiar.", "It looked like my old illness.", "For a period Đất Thủ hired quite a few managers. People came and went. Some didn't pass probation. Some went a stretch and stopped. Bần đạo was quite baffled then. “Hey, they've been managers before, haven't they?” “Do I really have to guide them on this?” “How come they don't know even this?”", "I believed in a principle that sounds wonderful: “If you trust, you must delegate.” So I delegated for real. Here is the goal. Here is the result. I trust you. Go ahead. In my head I called that empowerment.", "Then a few days later it began: “Where are you on this?” “Yes, I'm working on it.” “Working… meaning how far?”", "Ah.", "The Old Manager from Chapter 4 began to possess me.", "Some tasks I thought took three days were still open a week later. Some tasks I thought I'd explained clearly, the person receiving them didn't know where to start. Bần đạo began to feel disappointed. “How can they not know how to do this?”", "Much later, while guiding someone through a task again, I suddenly asked: “Has anyone ever told you this before?” “No.” “And this?” “Not that either, boss.” “Then how did you know to do it this way?”", "They looked at me. Bần đạo looked at them. The air began to smell of enlightenment.", "It turns out some things I'd done for years, so I took them as common knowledge. A new person would surely… download it themselves. The context unsaid. The expectations unclear. The way I want us to work together, unsaid. And then Bần đạo sat waiting for people to do exactly what was in his head.", "This technique turns out harder than Mind Reading (Tha Tâm Thông). Because this time I was asking staff to read the mind of the CEO.", "This afternoon, after the two conversations, the old illness flared up a little. Bần đạo was about to think: “Why do I have to say this too?” Luckily I stopped in time.", "Yes.", "Sometimes you have to say it plainly. Because…", "I never said it."]}, "anh-tin-em-nhung-khong-chon-em": {"title": "I trust you, but I'm not choosing you", "body": ["Five years ago there was an afternoon I still remember. Across from me sat an older brother figure, the tea between us going cold. He said he would not work with me. Just like that. I went home and all I thought was: maybe he doesn't trust me enough.", "A few years later, we sat over coffee again. Not about work at all, he suddenly said: “Back then, I didn't choose you, and it wasn't because I didn't trust you.”", "I went quiet. It seemed this sentence had been waiting five years.", "He said he trusted me as a person. Enthusiastic, yes, open to learning, yes. But the job mattered so much to him, and at that time… I wasn't yet strong enough to do it.", "It hurt a little to hear. But strangely, hearing it five years later, I no longer felt as upset as before. Maybe because Bần đạo has since changed seats. Before, I was the one waiting to be chosen. Now I'm the one who has to choose.", "And there are times I meet someone very good, very responsible, very willing. I like them a lot. But when it's time to place them in an important position, my hand stops.", "I used to think: “If you trust, you must delegate.” Now, when I'm about to say that, I remember the cup of tea from that day.", "Once someone asked almost exactly what I once wanted to ask: “You don't trust me?” Bần đạo almost answered at once. Then paused.", "“I trust you. But for this job, I'm not yet brave enough to choose you.”", "The two sentences side by side sound a bit contradictory. Five years ago I didn't understand either. In fact, that older brother had only said “no”; the part “he doesn't trust me” was something Bần đạo filled in himself.", "I hadn't even mastered Mind Reading (Tha Tâm Thông), yet back then I used it with great confidence. It took five years to learn… I'd mistranslated.", "Now it's my turn to sit on the other side of the table. Only now I see that not choosing someone is sometimes a hard thing to say.", "That older brother, it seems, was a whole realm above me in skill. At least he dared not to choose me.", "And me, back then…", "only wanted to be chosen."]}, "ca-khong-thay-nuoc": {"title": "The fish can't see the water", "body": ["In high school, I went to school because my parents made me. I didn't object. I had no burning desire to be first, either. There was only one thing I wanted… not to lose to anyone, not to be reprimanded, not to have my parents called in.", "In my first working years, it was the same. Not the best. Not the worst. Just somewhere in the middle, enough that the boss wouldn't notice. I thought that was normal.", "Now, after thirty years and one failure, I know that a fish that lives its whole life in water never sees the water. It thinks water is air. It thinks that's everything.", "My whole life I swam in one whispered sentence: “Don't lose. Good enough is fine.”", "In high school, afraid of the parent summons. At work, afraid of the boss's evaluation. In life, afraid of being seen as lesser. Every stage of life, the same sentence. Only the stage changed.", "I didn't choose this whisper on purpose. It came by itself, like a fear everyone has. I just didn't see another way.", "In 2016, I opened the company. The first two years I ran inside familiar territory. In 2018, I stepped into a project bigger than my familiar territory. More complex. Touching things I had never done. By 2019, I failed. Badly. I had to pay contract compensation. The financial loss was very large.", "In the nights after, there was one question I could not avoid: “How did I get here?” Not to this failure. To the place where I had stood my whole life, the place of just enough, no more.", "The most painful answer I found: I didn't fail because I did something wrong. I failed because, for the first time, there was a project too big for my “just enough” way of living.", "When a fish is thrown out of the water, for the first time it sees water. Because for the first time it has no water to swim in.", "Before 2018, I had my successful stretches: good scale, working alongside my colleagues, profit. I took that as proof that I was right. Now I know: that success wasn't because I was right. It was because the old tank still fit me. A fish swimming well in a familiar tank doesn't mean it knows it's in water.", "After the failure, I continued in architecture and construction, close to the interior design I had studied. For the first two years the company ran without a philosophy. I did it because I had to. The same old way of living, only a new trade.", "Until I read a book by Kazuo Inamori and found a sentence for the company: serve with kindness. A philosophy at last. Two philosophy-less years ended.", "But three years later, a staff member asked: “What are our company's vision and mission?” I sat with that question. I couldn't answer. The question was too big. Or, to be more honest, my knowledge wasn't enough to answer. In the end I had to hire an outside expert to help find the answer.", "A forty-year-old CEO, years in business, eleven years of meditation, still had to hire someone else to see what he wanted for his own company.", "This is the hardest thing for me to say today: eleven years of meditation did not let me see the water.", "Meditation taught me to observe small reactions in the mind: anger, joy, fear. But it doesn't automatically show me the way I've lived my whole life. That is too big. It's what I'm living inside. A fish that meditates for eleven years is still a fish. Still can't see the water by itself. Someone has to stand outside the tank and point: “There, you're inside that,” and only then does the fish see.", "I avoided the vision question for two years, and not because I forgot. I avoided it by saying “this question is too vague.” By “I'll think about it when I'm free.” By doing small things first. The fish is busy swimming. The fish has no time to see the water.", "Today I have a philosophy from Inamori. A vision and mission thanks to an expert. Eleven years of meditation. And the failures of 2018 and 2019 that taught me to see. But on hard nights, after a tense meeting, after a big decision, after a client says no, the mind still says: “Good enough is fine. Don't try too hard.”", "The old whisper is still there. After everything.", "The difference is that now I can hear it. Before, it spoke and I believed it at once. Now, when it speaks, there is a small gap before I believe. In that gap I get to ask: “Is this wise mind, or old habit flowing?”", "Most of the time I can't tell. Sometimes I can. That is the whole difference.", "A fish that sees the water still can't leave the water. The fish still has to swim in it. The difference is that the fish knows it is swimming. The old way of living doesn't disappear after I see it. It just leads me less. That is all that eleven years of practice have given me, and I've accepted that.", "The question I want to leave, not about meditation, not about failure:", "What is flowing around you that you take to be air?", "It might be an old whispered sentence. It might be a fear so familiar you no longer see it as fear. It might be a safe way of living so familiar you think it is you.", "Thirty years of my life, I didn't see the water. I stumbled into a big failure to see it. You don't need to go that far to see. Maybe all it takes is one question asked at the right time."]}, "tu-tin-hay-nga-man": {"title": "Confidence or conceit: looking back at myself after 5 years, from an old post", "body": ["I wonder if you've ever stumbled on an old diary entry, an old status, or a moment you were once proud of, and suddenly found it… funny?", "You think, how naive I was then. It was sincere, really, but a little rash. A kind of young confidence, or to put it bluntly, conceit I couldn't see at the time.", "This morning I fell into exactly such a moment. By chance I reread a post from five years ago, after a visit to the VNG office. Its title then was: “Having it but not knowing how to enjoy it… Sáng Trần, ignorant!”", "At the time, I believed I was being very “humble.” I told myself our team wasn't yet equal to theirs, but not worse either. I was confident that our people were very capable, just… without the conditions yet. It sounded reasonable. It even sounded like positive encouragement.", "But reading it this morning… I felt embarrassed. Because I realized that version of me had a touch of… subtle conceit.", "Conceit isn't always boasting. It's when a voice in your head whispers: “They're good, but we're not so far behind…” It isn't loud. It isn't showy. But it is a very clever layer of defense for the ego. A confidence not yet ripe.", "Now, when I step into a similar environment, I no longer feel the need to compare. I no longer think “we could do that too.” I only see clearly: I still have much to learn. And I'm fortunate to still have the chance to keep learning.", "Real confidence, perhaps, is daring to see your own insufficiency clearly, and still being at peace. Not to blame yourself. Not to prove anything. Just to keep living kindly and learning every day.", "I remember a teaching of Ajahn Chah: “The wise person is like the earth. Whatever filth or rubbish is dumped on it, it receives, and transforms. The conceited person, at one word against their will, bounces back.” May I learn to be earth. To settle. To receive. And to keep transforming.", "And then, writing this far… I ask myself: “If someone is trying not to be conceited, isn't that another kind of conceit?”", "I don't know the answer. I only know… I probably still have more to learn."]}}; var UI = { vi: { hero: "Những chuyện gặp khi làm nghề và làm người, kể lại để tự soi.", newest: "Bài mới", read: "Đọc bài", all: "Tất cả", back: "← Tất cả bài viết", mins: "phút đọc", own: "Ghi cho riêng bạn", ph: "Điều bạn nhận ra khi đọc, nếu có.", local: "Chỉ lưu trong trình duyệt này, không gửi đi đâu.", foot: "Soi mình thấy người. Soi người thấy mình.", about: "Về Sáng", brand: "Sáng Trần", site: "Sáng Trần Viết", mach: { "Chuyện thật": "Chuyện thật" }, tag: {} }, en: { hero: "Things I run into at work and in life, retold so I can look at myself.", newest: "Latest", read: "Read", all: "All", back: "← All posts", mins: "min read", own: "Just for you", ph: "What you noticed while reading, if anything.", local: "Saved only in this browser. Sent nowhere.", foot: "Look at yourself, see others. Look at others, see yourself.", about: "About", brand: "Sáng Trần", site: "Sáng Trần Writes", mach: { "Chuyện thật": "True story" }, tag: { "Học phí": "Tuition" } } }; var lang = "vi"; try { lang = localStorage.getItem("lang") || ((navigator.language || "").toLowerCase().indexOf("vi") === 0 ? "vi" : "en"); } catch (e) {} if (lang !== "en") lang = "vi"; POSTS.forEach(function (p) { var e = EN[p.slug]; if (e) p.en = { title: e.title, body: e.body.map(function (t, i) { return { t: t, beat: !!(p.body[i] && p.body[i].beat) }; }) }; }); function fd(d) { if (!d || lang !== "en") return d; var m = d.split("/"); var mon = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][parseInt(m[1], 10) - 1]; return parseInt(m[0], 10) + " " + mon + " " + m[2]; } function ui(k) { return UI[lang][k]; } function view(p) { return (lang === "en" && p.en) ? p.en : p; } function setLang(l) { lang = l; try { localStorage.setItem("lang", l); } catch (e) {} document.documentElement.lang = l; route(); } document.documentElement.lang = lang;
var app = document.getElementById("app"); var stage = document.getElementById("stage"); var activeTag = null;
function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
function readTime(post) { var words = view(post).body.map(function (b) { return b.t; }).join(" ").split(/\s+/).length; return Math.max(1, Math.round(words / 200)) + " " + ui("mins"); }
function topBar() { var bar = el("div", "top"); var home = el("a", null, ui("brand")); home.href = "#"; bar.appendChild(home); var about = el("a", null, ui("about")); about.href = "#ve-sang"; bar.appendChild(about); var sw = el("span", "lang"); ["vi", "en"].forEach(function (l, i) { if (i) sw.appendChild(document.createTextNode(" / ")); var b = el("button", null, l.toUpperCase()); b.type = "button"; b.setAttribute("aria-pressed", String(lang === l)); b.style.cssText = "background:none;border:0;padding:0;font:inherit;letter-spacing:inherit;cursor:pointer;color:inherit;opacity:" + (lang === l ? "1" : ".45") + ";"; b.addEventListener("click", function () { setLang(l); }); sw.appendChild(b); }); bar.appendChild(sw); return bar; }
/* Trang "Về Sáng". photo: đặt đường dẫn hoặc data URI ảnh thật vào đây khi có; để trống thì không hiện ảnh. */ var ABOUT = { photo: "https://sangtran-create.github.io/sangtran-viet/photo.jpg", en: [ "I build houses in Thủ Dầu Một. My family is from Nghệ An. In 2016 I started Đất Thủ, and in 2019 I took on a project bigger than I could carry, then kept going in architecture and construction.", "I have sat in meditation since 2015, and have never once dared to call myself good at it.", "This blog is where I retell what I run into at work and in life. Told so I can look at myself. Maybe you have been there too.", "A note on words: “Bần đạo” is how I mock myself, a humble monk. “Tâm Ma” is the inner voice that argues against practice, and argues well." ], paras: [ "Mình làm nhà ở Thủ Dầu Một. Quê Nghệ An. Năm 2016 mở Đất Thủ, đến 2019 vấp một dự án lớn hơn sức mình, rồi đi tiếp bằng nghề kiến trúc và xây dựng.", "Ngồi thiền từ 2015, chưa lúc nào dám nói là giỏi.", "Blog này là chỗ mình kể lại những chuyện gặp khi làm nghề và làm người. Kể để tự soi. Có thể anh chị cũng từng như vậy." ] };
function renderAbout() { app.textContent = ""; app.appendChild(topBar()); var back = el("a", "back", ui("back")); back.href = "#"; app.appendChild(back); var art = el("article", "post"); art.appendChild(el("h1", "cast", ui("about"))); if (ABOUT.photo) { var img = el("img"); img.src = ABOUT.photo; img.alt = "Sáng Trần"; img.onerror = function () { img.remove(); }; img.style.cssText = "width:100%;max-width:16rem;height:auto;display:block;margin:0 0 2rem;"; art.appendChild(img); } var body = el("div", "body"); (lang === "en" ? ABOUT.en : ABOUT.paras).forEach(function (t) { body.appendChild(el("p", null, t)); }); art.appendChild(body); app.appendChild(art); app.appendChild(footer()); document.title = ui("about") + " | " + ui("site"); window.scrollTo(0, 0); drift(); }
function footer() { return el("div", "foot", ui("foot")); }
function allTags() { var seen = []; POSTS.forEach(function (p) { (p.tags || []).forEach(function (t) { if (seen.indexOf(t) < 0) seen.push(t); }); }); return seen; }
function renderHome() { app.textContent = ""; app.appendChild(topBar());
var hero = el("section", "hero"); hero.appendChild(el("h1", "cast", ui("hero"))); app.appendChild(hero);
var visible = POSTS.filter(function (p) { return !activeTag || (p.tags || []).indexOf(activeTag) >= 0; });
if (visible.length) { var first = visible[0]; var lead = el("section", "lead"); var a = el("a"); a.href = "#" + first.slug; a.appendChild(el("p", "label", first.date ? ui("newest") + " · " + fd(first.date) : ui("newest"))); a.appendChild(el("h2", "cast", view(first).title)); a.appendChild(el("p", null, view(first).body[0].t)); a.appendChild(el("span", "more", ui("read"))); lead.appendChild(a); app.appendChild(lead); }
var tags = allTags(); if (tags.length > 1) { var filters = el("div", "filters"); var all = el("button", "chip", ui("all")); all.type = "button"; all.setAttribute("aria-pressed", String(!activeTag)); all.addEventListener("click", function () { activeTag = null; renderHome(); }); filters.appendChild(all); tags.forEach(function (t) { var c = el("button", "chip", ui("tag")[t] || t); c.type = "button"; c.setAttribute("aria-pressed", String(activeTag === t)); c.addEventListener("click", function () { activeTag = t; renderHome(); }); filters.appendChild(c); }); app.appendChild(filters); }
var rest = visible.slice(1); if (rest.length) { var list = el("ul", "list"); rest.forEach(function (p) { var li = el("li", "row"); var a2 = el("a"); a2.href = "#" + p.slug; a2.appendChild(el("time", null, fd(p.date) || "·")); a2.appendChild(el("h3", null, view(p).title)); li.appendChild(a2); list.appendChild(li); }); app.appendChild(list); }
if (POSTS.length === 1 && POSTS[0].mach === "Bài mẫu") { app.appendChild(el("p", "note", "Blog đang chờ bài đầu tiên. Bài ở trên là bài mẫu để xem cách trình bày, chưa phải chuyện thật.")); }
app.appendChild(footer()); document.title = ui("site"); window.scrollTo(0, 0); drift(); }
function loadNote(slug) { try { return localStorage.getItem("note:" + slug) || ""; } catch (e) { return ""; } } function saveNote(slug, value) { try { localStorage.setItem("note:" + slug, value); } catch (e) { /* chỉ là tiện ích, bỏ qua */ } }
function renderPost(post) { app.textContent = ""; app.appendChild(topBar());
var back = el("a", "back", ui("back")); back.href = "#"; app.appendChild(back);
var art = el("article", "post"); art.appendChild(el("p", "meta", (post.date ? fd(post.date) + " · " : "") + readTime(post) + " · " + (ui("mach")[post.mach] || post.mach))); art.appendChild(el("h1", "cast", view(post).title));
var body = el("div", "body"); view(post).body.forEach(function (b) { body.appendChild(el("p", b.beat ? "beat" : null, b.t)); }); art.appendChild(body);
var own = el("section", "own"); own.appendChild(el("p", "label", ui("own"))); var ta = el("textarea"); ta.id = "own-note"; ta.setAttribute("aria-label", "Ghi chú riêng của bạn"); ta.placeholder = ui("ph"); ta.value = loadNote(post.slug); ta.addEventListener("input", function () { saveNote(post.slug, ta.value); }); own.appendChild(ta); own.appendChild(el("small", null, ui("local"))); art.appendChild(own); app.appendChild(art);
app.appendChild(footer()); document.title = view(post).title + " | " + ui("site"); window.scrollTo(0, 0); drift(); }
/* Ánh sáng trôi: lớp gần trôi nhanh hơn lớp xa */ var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches; var ticking = false; function drift() { if (reduce) return; var y = window.scrollY || 0; stage.style.setProperty("--bx", (-y * 0.03).toFixed(1) + "px"); stage.style.setProperty("--by", (-y * 0.07).toFixed(1) + "px"); stage.style.setProperty("--bx2", (-y * 0.015).toFixed(1) + "px"); stage.style.setProperty("--by2", (-y * 0.035).toFixed(1) + "px"); } window.addEventListener("scroll", function () { if (ticking) return; ticking = true; window.requestAnimationFrame(function () { ticking = false; drift(); }); }, { passive: true });
function route() { var slug = (location.hash || "").replace(/^#/, ""); var found = POSTS.filter(function (p) { return p.slug === slug; })[0]; if (slug === "ve-sang") renderAbout(); else if (found) renderPost(found); else renderHome(); }
window.addEventListener("hashchange", route); route();
